  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C43"],
      "claim": "Tolbutamide, a direct arylsulfonylurea analogue, has absolute human oral bioavailability of 80–90%; the query shares the same sulfonylurea pharmacophore, strongly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "The closest retrieved analogue, a tolyl urea, has human oral bioavailability of 0.7857, supporting high F despite moderate structural similarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Recainam, a tolyl urea with an isopropylamine side chain, has absolute bioavailability of 73% in healthy men; shared tolyl/urea/isopropyl features support high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Pimasertib, a pyridine anilino amide, has absolute oral bioavailability of 73% in humans; shared pyridine/aniline/amide features support high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Belumosudil, a heteroaromatic isopropyl-containing drug, has absolute oral bioavailability of 64% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Lisofylline has low human oral bioavailability of 5.9%, but its structure is dissimilar and lacks the sulfonylurea core, so this is weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a sulfonylurea-containing molecule. Direct sulfonylurea analogue tolbutamide shows 80–100% human F, and multiple moderately similar aryl urea/heteroaryl anilines show 64–90% absolute F. The only low-F record is structurally distant and does not outweigh the consistent high-F evidence.",
  "evidence_gaps": [
    "No direct human pharmacokinetic measurement for the exact query molecule.",
    "No query-specific data on metabolism, efflux, or solubility are available.",
    "Bupropion records are conflicting and structurally distant, so they were not used as decisive evidence.",
    "The mechanism underlying the low lisofylline bioavailability is unclear and its structural dissimilarity limits transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

